const inputItem = $input.first();

// Texto vindo do body
const text = inputItem.json.body.prompt;

// transforma em objeto chave: valor
const pairs = text.split(",").map(item => item.trim());

let data = {};

pairs.forEach(pair => {
  const [key, value] = pair.split(":").map(p => p.trim());
  if (key && value) {
    data[key.toLowerCase()] = value;
  }
});

// Normalização
const context = {
  mode: data["modo"] === "Gerar Look" ? "GENERATE" : "EDIT",
  context: data["contexto"]?.toUpperCase(),
  period: data["momento"]?.toUpperCase(),
  temperature: data["clima"]?.toUpperCase(),
  formality: parseInt(data["nível de formalidade"]),
  style: data["estilo"]?.toUpperCase().replace(/\s+/g, "_"),
  closet_toggle: data["priorizar meu armário"] === "on"
};

// Retorna JSON + binaries preservadas
return [{
  json: { context },
  binary: inputItem.binary
}];

const items = $input.all();

let finalJson = {};
let finalBinary = {};

for (const item of items) {
  if (item.json) {
    finalJson = { ...finalJson, ...item.json };
  }

  if (item.binary) {
    finalBinary = { ...finalBinary, ...item.binary };
  }
}

return [{
  json: finalJson,
  binary: finalBinary
}];

// Pega o texto completo vindo do Agent
const fullText = $json.output || "";

// Divide pelas seções
const section1Match = fullText.match(/SECTION 1[\s\S]*?SECTION 2/);
const section2Match = fullText.match(/SECTION 2[\s\S]*/);

let prompt_edit = "";
let justificativa = "";

if (section1Match) {
  prompt_edit = section1Match[0]
    .replace(/SECTION 1\s*—?\s*LOOK COMPLETO/i, "")
    .replace(/SECTION 2[\s\S]*/i, "")
    .trim();
}

if (section2Match) {
  justificativa = section2Match[0]
    .replace(/SECTION 2\s*—?\s*JUSTIFICATIVA COMPLETA/i, "")
    .trim();
}

return [{
  json: {
    ...$json,
    prompt_edit,
    justificativa
  },
  binary: $binary
}];

